/* ---------------------------------------------------------------
 * Stylelint
 *
 * Lints the design system's CSS. tokens.css is generated by Style
 * Dictionary; src/app/globals.css is legacy Tailwind and joins when
 * the app migrates to the design system.
 * --------------------------------------------------------------- */

const KEBAB_CASE = '^[a-z][a-z0-9]*(-[a-z0-9]+)*$';

/**
 * Custom properties that Radix sets at runtime on the elements it positions,
 * so no stylesheet declares them (e.g. the Select list's width and height).
 */
const RADIX_RUNTIME_PROPERTIES = {
  customProperties: {
    '--radix-select-trigger-width': 'auto',
    '--radix-select-content-available-height': 'auto',
    '--radix-select-content-transform-origin': 'center',
  },
};

/** A `--ds-*` token that is not semantic (tier 2) or component (tier 3), i.e. tier 1. */
const TIER_ONE_TOKEN = '/var\\(\\s*--ds-(?!semantic-|component-)/';

/** @type {import('stylelint').Config} */
export default {
  extends: ['stylelint-config-recommended'],
  plugins: ['stylelint-value-no-unknown-custom-properties'],
  ignoreFiles: ['src/components/design-system/tokens/tokens.css', 'src/app/globals.css'],
  rules: {
    // State rules exclude each other with :not(:disabled), so a later, less specific
    // :disabled rule cannot be overridden by the :active one above it.
    'no-descending-specificity': null,
    // Components read class names with bracket access: styles['error-icon'].
    'selector-class-pattern': [
      KEBAB_CASE,
      { message: (selector) => `Expected class "${selector}" to be kebab-case` },
    ],
  },
  overrides: [
    {
      files: ['src/components/design-system/**/*.css'],
      rules: {
        // A misspelled token is silent in CSS: var(--ds-typo) resolves to nothing.
        'csstools/value-no-unknown-custom-properties': [
          true,
          {
            importFrom: [
              'src/components/design-system/tokens/tokens.css',
              RADIX_RUNTIME_PROPERTIES,
            ],
          },
        ],
        // Component styles use tier 2 and tier 3 only, so theming can swap them.
        'declaration-property-value-disallowed-list': [
          { '/.*/': [TIER_ONE_TOKEN] },
          {
            message:
              'Use a semantic (--ds-semantic-*) or component (--ds-component-*) token, not tier 1',
          },
        ],
      },
    },
  ],
};
